# Receitas acrescentadas na 2.ª leva + metadados extra (dificuldade, conservação, unidade, frase de abertura da narração)
# para todas as receitas. Importado por recipes_src.py.
def G(q, name, food): return {'q': q, 'u': 'g', 'n': name, 'food': food}
def U(q, sing, plur, food, grams=None): return {'q': q, 'u': 'un', 'n': sing, 'np': plur, 'food': food, 'grams': grams}
def CS(q, name, food): return {'q': q, 'u': 'c. sopa', 'n': name, 'food': food}
def CC(q, name, food): return {'q': q, 'u': 'c. chá', 'n': name, 'food': food}
def T(text): return {'t': text}
def sh(shape, c, n=4): return {'k': 'shape', 'shape': shape, 'c': c, 'n': n}
def g(id, shape, c, n=None, **kw):
    d = dict(id=id, shape=shape, c=c)
    if n is not None: d['n'] = n
    d.update(kw); return d
def B(groups, *text): return dict(groups=groups, text=list(text))
def FX(fx, *text, spice=None):
    d = dict(fx=fx, text=list(text))
    if spice: d['spice'] = spice
    return d
PRE = lambda t: dict(kind='preheat', temp=t, title=['Pré-aquece', 'o forno'])

